import itertools
from collections import Counter

def check_m(m):
    # All possible multisets of size m from {0, ..., m-1}
    for a in itertools.combinations_with_replacement(range(m), m):
        sum_a = sum(a)
        if sum_a % m == 0:
            continue

        # Check if any permutation p of a satisfies sum((j+1)*p[j] for j in range(m)) % m == 0
        # Use DP to find all possible sums
        # dp[k][s] = possible to get sum s using k elements from a
        # To track elements used, we can use a tuple of counts of each value in {0, ..., m-1}

        counts = Counter(a)
        distinct_elements = sorted(counts.keys())
        counts_tuple = tuple(counts[e] for e in distinct_elements)

        # dp[k][current_counts] = set of possible sums
        # This is still too large. 
        # Let's use a simpler DP:
        # dp[k][sum] = set of possible counts_tuples

        possible_sums = {0}
        current_counts = Counter()

        # This is still not quite right. 
        # Let's use: dp[k] = set of (sum, counts_tuple)
        dp = {(0, tuple([0] * len(distinct_elements)))}
        for k in range(1, m + 1):
            next_dp = set()
            for s, c_tuple in dp:
                for i, e in enumerate(distinct_elements):
                    if c_tuple[i] < counts_tuple[i]:
                        next_c_tuple = list(c_tuple)
                        next_c_tuple[i] += 1
                        next_dp.add(((s + k * e) % m, tuple(next_c_tuple)))
            dp = next_dp

        found_perm = False
        for s, c_tuple in dp:
            if s == 0:
                found_perm = True
                break

        if not found_perm:
            return False
    return True

for m in range(2, 12):
    print(f"m={m}: {check_m(m)}")

import itertools

def check_m_fast(m):
    for a in itertools.combinations_with_replacement(range(m), m):
        if sum(a) % m == 0:
            continue

        found_perm = False
        for p in itertools.permutations(a):
            if sum((j + 1) * p[j] for j in range(m)) % m == 0:
                found_perm = True
                break
        if not found_perm:
            return False
    return True

for m in range(2, 10):
    print(f"m={m}: {check_m_fast(m)}")

import itertools

def find_counterexample(m):
    for a in itertools.combinations_with_replacement(range(m), m):
        if sum(a) % m == 0:
            continue

        found_perm = False
        for p in itertools.permutations(a):
            if sum((j + 1) * p[j] for j in range(m)) % m == 0:
                found_perm = True
                break
        if not found_perm:
            return a
    return None

