import random

def check_m_random(m, num_multisets=500, num_shuffles=1000):
    for _ in range(num_multisets):
        a = [random.randint(0, m-1) for _ in range(m)]
        if sum(a) % m == 0:
            continue

        found = False
        for _ in range(num_shuffles):
            random.shuffle(a)
            if sum((j+1)*a[j] for j in range(m)) % m == 0:
                found = True
                break
        if not found:
            return False
    return True

