def check_multiset(m, a):
    import itertools
    # a is a multiset. Let's just try all permutations if m is small.
    for p in itertools.permutations(a):
        if sum((j+1)*p[j] for j in range(m)) % m == 0:
            return True
    return False

print(f"m=10, a=(1,1,1,1,1,1,1,1,1,3): {check_multiset(10, (1,1,1,1,1,1,1,1,1,3))}")
